/* ---------- transport ---------- */
const T = { playing: false, rec: false, cursor: 0, slot: 0, next: 0, loop: true, loopA: 0, loopB: null, metro: true, q: [], srcs: [], timer: 0, bars: null, wantRec: false, recFrom: 0, startCursor: 0, ending: false };
