  cases.push(mk('Strummed chords', chs.map(c => [[0, c.sh], [8, c.sh.slice().reverse().slice(0, Math.max(3, c.sh.length - 1)).reverse()]]), k => chs[Math.floor(k / spb())] && chs[Math.floor(k / spb())].s));
