  const bm = []; for (let i = 0; i < 4; i++) { const s = pick(syms), sh = shape(s); if (!sh) continue; const lo = sh[0], b = [[0, [lo]]]; let f = pick([1, 3, 5]); [4, 6, 8, 12].forEach(sl => { f = clamp(f + pick([-2, -1, 1, 2]), 0, 10); b.push([sl, [[pick([4, 5]), f]]]); }); bm.push({ s, b }); }
