    const song = o.song || (kind === 'demo' ? (() => { const d = demoSong(); d.sections.forEach(sec => sec.bars.forEach(b => { const c = barChords(b)[0]; if (c) fillTab(b, 'Fingerstyle pop', c); })); return d; })() : blankSong(o));
