  if (/\.(txt|md|lrc)$/.test(n) || t === 'text/plain' || t === 'text/markdown') return 'lyrics';
  if (/\.json$/.test(n) || t === 'application/json') return 'json';
  if (/\.(mid|midi|kar)$/.test(n) || t === 'audio/midi' || t === 'audio/x-midi') return 'midi';
