  /* F#/Gb major and D#/Eb minor can be spelled either way: keep the sharps or flats the song already uses */
  const either = S.minor ? key === 3 : key === 6, sharp = S.sections.some(s => s.bars.some(b => /#/.test(b.chord || '')));
